+        return new ParamSearchId(
+                "PS-"
+                        + DateTimeFormatter.BASIC_ISO_DATE.format(date)
+                        + "-"
+                        + String.format("%06d", sequence));
+    }
+
+    /** 저장된 문자열을 형식 검증과 함께 복원한다. */
+    public static ParamSearchId from(String value) {
+        return new ParamSearchId(value);
+    }
+}

